$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$showcase = Join-Path $root "showcase"
$utf8 = New-Object System.Text.UTF8Encoding($false)
function Write-Source($relative, $content) {
  $path = Join-Path $showcase $relative
  $parent = Split-Path -Parent $path
  New-Item -ItemType Directory -Force -Path $parent | Out-Null
  [System.IO.File]::WriteAllText($path, $content + [Environment]::NewLine, $utf8)
}

$header = @'
"use client";
import Link from "next/link";
import { Button } from "antd";
import { usePathname } from "next/navigation";
import styles from "./CrispixHeader.module.css";

export function CrispixHeader() {
  const pathname = usePathname();
  const links = [["/zh", "\u9996\u9875"], ["/zh/agent", "AI\u667a\u80fd\u4f53"], ["/zh/tool", "\u5de5\u5177\u7bb1"], ["/zh/pricing", "\u4ef7\u683c\u65b9\u6848"]];
  return <header className={styles.header}><Link href="/zh" className={styles.logo}><span>C</span><b>Crispix</b></Link><nav>{links.map(([href, label]) => <Link key={href} href={href} className={pathname === href ? styles.active : ""}>{label}</Link>)}</nav><div className={styles.actions}><Link href="/login" className={styles.login}>\u767b\u5f55</Link><Button type="primary" href="/zh/agent">\u5f00\u59cb\u4f7f\u7528</Button></div></header>;
}
'@
