.page{min-height:100vh;background:#f8fafc;color:#1e293b}.intro{max-width:730px;padding:82px 20px 48px;margin:auto;text-align:center}.intro>p{color:#3a86ff;font-size:10px;font-weight:800;letter-spacing:.2em}.intro h1{margin:15px 0 12px;font-family:Georgia,"Noto Serif SC",serif;font-size:56px;font-weight:400;letter-spacing:-.07em}.intro span{display:block;color:#475569;font-size:17px}.intro small{display:block;margin-top:10px;color:#94a3b8;font-size:12px}.filters{display:flex;justify-content:space-between;max-width:1180px;padding:0 20px 24px;margin:auto;border-bottom:1px solid #e7edf5}.filters div{display:flex;gap:7px}.filters button{padding:8px 13px;color:#64748b;cursor:pointer;background:#fff;border:1px solid #e2eaf4;border-radius:8px;font-size:12px}.filters button b{margin-left:5px;color:#94a3b8;font-size:10px}.filters .chosen{color:#fff;background:#3a86ff;border-color:#3a86ff}.filters .chosen b{color:#dceaff}.filters :global(.ant-input-affix-wrapper){width:180px;border-radius:8px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;max-width:1180px;padding:30px 20px 50px;margin:auto}.card{overflow:hidden;color:#1e293b;text-decoration:none;background:#fff;border:1px solid #e2eaf4;border-radius:12px;box-shadow:0 2px 8px #3a86ff0b;transition:.2s}.card:hover{border-color:#3a86ff;box-shadow:0 9px 25px #3a86ff18;transform:translateY(-3px)}.imageWrap{position:relative}.imageWrap img{display:block;width:100%;height:170px;object-fit:cover;background:#eef4fc}.imageWrap :global(.ant-tag){position:absolute;top:10px;left:10px;margin:0;border-radius:5px}.cardBody{padding:15px}.cardBody>small{color:#94a3b8;font-size:10px}.cardBody h2{overflow:hidden;margin:9px 0 7px;font-size:15px;text-overflow:ellipsis;white-space:nowrap}.cardBody p{min-height:38px;margin:0 0 17px;color:#64748b;font-size:11px;line-height:1.65}.cardBody>span{color:#3a86ff;font-size:10px;font-weight:600}.more{padding:0 20px 50px;color:#94a3b8;text-align:center;font-size:12px}@media(max-width:950px){.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.intro{padding:55px 20px 35px}.intro h1{font-size:44px}.filters{display:block}.filters div{overflow:auto;padding-bottom:12px}.filters :global(.ant-input-affix-wrapper){width:100%}.grid{grid-template-columns:repeat(2,1fr);gap:10px;padding-top:20px}.imageWrap img{height:130px}.cardBody{padding:11px}.cardBody p{min-height:56px}}@media(max-width:430px){.grid{grid-template-columns:1fr}}
