$pricing = @'
"use client";
import { useState } from "react";
import { Button, Segmented } from "antd";
import { CheckOutlined } from "@ant-design/icons";
import { CrispixHeader } from "../../../components/CrispixHeader";
import styles from "./page.module.css";
const plans=[{name:"\u57fa\u7840\u7248",desc:"\u9002\u5408\u4e2a\u4eba\u7528\u6237\u548c\u5c0f\u578b\u9879\u76ee",month:129,year:99,features:["\u6bcf\u6708 1,000 \u6b21 API \u8c03\u7528","\u57fa\u7840\u56fe\u50cf\u8bc6\u522b","\u6807\u51c6\u54cd\u5e94\u901f\u5ea6","\u90ae\u4ef6\u652f\u6301","\u57fa\u7840\u6587\u6863"]},{name:"\u4e13\u4e1a\u7248",desc:"\u9002\u5408\u4e2d\u5c0f\u4f01\u4e1a\u548c\u56e2\u961f\u4f7f\u7528",month:399,year:299,hot:true,features:["\u6bcf\u6708 10,000 \u6b21 API \u8c03\u7528","\u9ad8\u7ea7\u56fe\u50cf\u8bc6\u522b","\u4f18\u5148\u54cd\u5e94\u901f\u5ea6","24/7 \u5728\u7ebf\u652f\u6301","\u5b8c\u6574\u6587\u6863\u548c SDK","\u56e2\u961f\u534f\u4f5c\u529f\u80fd"]},{name:"\u4f01\u4e1a\u7248",desc:"\u9002\u5408\u5927\u578b\u4f01\u4e1a\u548c\u9ad8\u9891\u4f7f\u7528",month:1299,year:999,features:["\u65e0\u9650 API \u8c03\u7528","\u4f01\u4e1a\u7ea7\u56fe\u50cf\u8bc6\u522b","\u6700\u9ad8\u4f18\u5148\u7ea7","\u4e13\u5c5e\u5ba2\u6237\u7ecf\u7406","\u79c1\u6709\u5316\u90e8\u7f72","SLA \u4fdd\u969c"]}];
export default function PricingPage(){const [annual,setAnnual]=useState(false);return <main className={styles.page}><CrispixHeader/><section className={styles.hero}><p>PRICING</p><h1>\u9009\u62e9\u9002\u5408\u60a8\u7684<br/><em>\u4ef7\u683c\u65b9\u6848</em></h1><span>\u7075\u6d3b\u7684\u5b9a\u4ef7\u65b9\u6848\uff0c\u6ee1\u8db3\u4e0d\u540c\u89c4\u6a21\u7528\u6237\u7684\u9700\u6c42\u3002</span><Segmented value={annual?"year":"month"} onChange={(value)=>setAnnual(value==="year")} options={[{label:"\u6309\u6708\u4ed8\u8d39",value:"month"},{label:"\u6309\u5e74\u4ed8\u8d39 \u770120%",value:"year"}]}/></section><section className={styles.plans}>{plans.map(plan=><article className={plan.hot?styles.hot:""} key={plan.name}>{plan.hot&&<b className={styles.recommend}>\u63a8\u8350</b>}<small>JENDA AGENT</small><h2>{plan.name}</h2><p>{plan.desc}</p><div className={styles.price}><span>¥</span>{annual?plan.year:plan.month}<small> / \u6bcf\u6708</small></div><ul>{plan.features.map(feature=><li key={feature}><CheckOutlined/>{feature}</li>)}</ul><Button type={plan.hot?"primary":"default"} block>{plan.name==="\u4f01\u4e1a\u7248"?"\u8054\u7cfb\u9500\u552e":"\u5f00\u59cb\u4f7f\u7528"}</Button></article>)}</section><section className={styles.compare}><h2>\u529f\u80fd\u5bf9\u6bd4</h2><div className={styles.table}><div>\u529f\u80fd\u7279\u6027</div><div>\u57fa\u7840\u7248</div><div>\u4e13\u4e1a\u7248</div><div>\u4f01\u4e1a\u7248</div>{[["API \u8c03\u7528\u6b21\u6570","1,000 / \u6708","10,000 / \u6708","\u65e0\u9650"],["\u56fe\u50cf\u8bc6\u522b\u7cbe\u5ea6","\u6807\u51c6","\u9ad8\u7ea7","\u4f01\u4e1a\u7ea7"],["\u6280\u672f\u652f\u6301","\u90ae\u4ef6","24/7 \u5728\u7ebf","\u4e13\u5c5e\u5ba2\u6237\u7ecf\u7406"],["\u79c1\u6709\u5316\u90e8\u7f72","-","-","\u652f\u6301"],["SLA \u4fdd\u969c","-","99.9%","99.99%"]].flatMap(row=>row.map((cell,i)=><span className={i===0?styles.label:""} key={`${row[0]}-${i}`}>{cell}</span>))}</div></section><footer>\u9700\u8981\u66f4\u591a\u5b9a\u5236\u5316\u529f\u80fd\uff1f \u8054\u7cfb\u6211\u4eec\uff0c\u83b7\u53d6\u79c1\u6709\u5316\u90e8\u7f72\u4e0e\u5b9a\u5236\u5f00\u53d1\u65b9\u6848\u3002</footer></main>}
'@
$pricingCss = @'
.page{min-height:100vh;background:#f8fafc;color:#1e293b}.hero{padding:85px 20px 55px;text-align:center}.hero>p{color:#3a86ff;font-size:10px;font-weight:800;letter-spacing:.2em}.hero h1{margin:15px 0;color:#1e293b;font-family:Georgia,"Noto Serif SC",serif;font-size:54px;font-weight:400;letter-spacing:-.07em;line-height:1.05}.hero h1 em{color:#3a86ff;font-style:normal}.hero>span{display:block;margin:0 auto 30px;color:#64748b;font-size:14px}.hero :global(.ant-segmented){padding:4px;background:#eaf2ff}.hero :global(.ant-segmented-item-selected){color:#fff;background:#3a86ff}.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;max-width:1050px;padding:0 20px 95px;margin:auto}.plans article{position:relative;padding:28px 25px;background:#fff;border:1px solid #e1e9f4;border-radius:12px;box-shadow:0 3px 12px #3a86ff0d}.plans article.hot{border:2px solid #3a86ff;box-shadow:0 12px 30px #3a86ff1f}.recommend{position:absolute;top:-13px;right:22px;padding:6px 10px;color:#fff;background:#3a86ff;border-radius:999px;font-size:10px}.plans article>small{color:#3a86ff;font-size:9px;font-weight:800;letter-spacing:.13em}.plans h2{margin:18px 0 8px;font-size:22px}.plans article>p{min-height:37px;margin:0;color:#64748b;font-size:12px}.price{padding:24px 0 18px;color:#1e293b;font-size:46px;font-weight:700}.price>span{margin-right:4px;color:#3a86ff;font-size:19px}.price small{color:#94a3b8;font-size:11px;font-weight:400}.plans ul{display:grid;gap:11px;min-height:177px;padding:17px 0;margin:0 0 20px;border-top:1px solid #edf2f8;list-style:none}.plans li{color:#475569;font-size:12px}.plans li :global(.anticon){margin-right:7px;color:#10b981}.plans :global(.ant-btn){height:38px;border-radius:8px}.plans :global(.ant-btn-primary){background:#3a86ff;box-shadow:0 3px 9px #3a86ff38}.compare{max-width:1050px;padding:80px 20px;margin:auto;border-top:1px solid #e7edf5}.compare h2{margin:0 0 25px;font-family:Georgia,"Noto Serif SC",serif;font-size:34px;font-weight:400}.table{display:grid;grid-template-columns:1.6fr repeat(3,1fr);overflow:hidden;background:#fff;border:1px solid #e2eaf4;border-radius:10px}.table>div,.table>span{padding:15px;border-right:1px solid #edf2f7;border-bottom:1px solid #edf2f7;color:#64748b;font-size:12px}.table>div:nth-child(-n+4){color:#1e293b;background:#f4f8ff;font-weight:700}.table .label{color:#334155;font-weight:600}.page>footer{max-width:1050px;padding:50px 20px 70px;margin:auto;color:#94a3b8;text-align:center;font-size:12px}@media(max-width:760px){.hero h1{font-size:43px}.plans{grid-template-columns:1fr;max-width:420px;padding-bottom:55px}.table{grid-template-columns:1.4fr repeat(3,100px);overflow:auto}.table>div,.table>span{white-space:nowrap}}
'@
Write-Source "app\zh\pricing\page.tsx" $pricing
Write-Source "app\zh\pricing\page.module.css" $pricingCss

